mapper.insert:
WITH upsert AS (
        UPDATE emp02_others
           SET emp02_person_id              = #{personId}
             , emp02_chn_nm                 = #{chnName}
             , emp02_ctz_no                 = to_encrypts(#{decCtzNo})
             , emp02_birthday               = #{birthday}
             , emp02_lunar_cd               = #{lunarCode}
             , emp02_eng_nm                 = #{engName}
             , emp02_gender_cd              = #{genderCode}
             , emp02_nat_cd                 = #{nationCode}
             , emp02_email_other            = #{emailOther}
             , emp02_military_cd            = #{militaryCode}
             , emp02_family_dscr            = #{familyDscr}
             , emp02_marriage_cd            = #{marriageCode}
             , emp02_zip_cd                 = #{zipCode}
             , emp02_zip_addr               = #{zipAddress}
             , emp02_addr_detail            = #{zipDetail}
             , emp02_home_telno             = #{homeTelNo}
             , emp02_note                   = #{note}
             , emp02_hire_date_group        = #{hireDateGroup}
             , emp02_hire_date_leave_calc   = #{hireDateLeaveCalc}
         WHERE emp02_others_id = #{othersId}
           AND emp02_person_id = #{personId}
     RETURNING *
)
    INSERT
      INTO emp02_others
         ( emp02_others_id
         , emp02_person_id
         , emp02_chn_nm
         , emp02_ctz_no
         , emp02_birthday
         , emp02_lunar_cd
         , emp02_eng_nm
         , emp02_gender_cd
         , emp02_nat_cd
         , emp02_email_other
         , emp02_military_cd
         , emp02_family_dscr
         , emp02_marriage_cd
         , emp02_zip_cd
         , emp02_zip_addr
         , emp02_addr_detail
         , emp02_home_telno
         , emp02_note
         , emp02_hire_date_group
         , emp02_hire_date_leave_calc
         )
    SELECT f_create_seq()
         , #{personId}
         , #{chnName}
         , to_encrypts(#{decCtzNo})
         , #{birthday}
         , #{lunarCode}
         , #{engName}
         , #{genderCode}
         , #{nationCode}
         , #{emailOther}
         , #{militaryCode}
         , #{familyDscr}
         , #{marriageCode}
         , #{zipCode}
         , #{zipAddress}
         , #{zipDetail}
         , #{homeTelNo}
         , #{note}
         , #{hireDateGroup}
         , #{hireDateLeaveCalc}
     WHERE NOT EXISTS ( SELECT * FROM upsert )
